    "updated_at" DATETIME NOT NULL,
    -- AUTH-1: 3 to 32 characters among a-z 0-9 . _ -, starting with a letter or a digit.
    CONSTRAINT "users_username_format" CHECK (
        length("username") BETWEEN 3 AND 32
